import{_ as i,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2019-08-06 :: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-08-06 :: Crimson SeaStor OSD Weekly Meeting","date":"2019-08-06T00:00:00.000Z","updated":"2019-08-12T00:00:00.000Z","tags":["Ceph","Distributed Storage","Crimson","OSD","Performance Testing"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-08-06_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-08-06_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-08-06_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function o(s,e,a,_,S,g){return t(),r("div",null,[...e[0]||(e[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>会议地点</strong>： 圣克拉拉</p><p><strong>参会人员</strong>： Marya, Peter, Suri, Rida, Milan, Comment, Justin</p><p><strong>会议内容</strong>：</p><p><strong>1. 复制副本测试</strong>：</p><ul><li>Marya汇报了其使用Crimson II进行复制副本测试的进展，未发现性能退步。</li><li>讨论了将测试合并到Merger的可行性，但需要Crimson Messenger的支持。</li><li>Marya将继续进行测试，并尝试将其合并到Merger。</li></ul><p><strong>2. 性能测试集成</strong>：</p><ul><li>讨论了将性能测试集成到Jenkins和Ritter的TD Site中。</li><li>需要比较不同测试用例的性能，包括Crimson II和Crimson Messenger。</li><li>计划编写SMO测试，比较基线性能。</li><li>将确保测试用例反映实际使用场景。</li></ul><p><strong>3. 对象存储设计</strong>：</p><ul><li>讨论了对象存储的设计，包括命名空间和硬件支持。</li><li>认识到需要支持不同的硬件，包括HDD和SSD。</li><li>讨论了Sister和Blue Store的差异和适用场景。</li></ul><p><strong>4. 其他议题</strong>：</p><ul><li>Suri汇报了其在Crimson中实现安全类和对象类的进展。</li><li>Rida讨论了Sitar输入缓冲区的实现，并计划与Avi面对面讨论。</li><li>Comment讨论了使用Python或批处理代码驱动测试的想法。</li><li>Milan讨论了将UNIX域套接字支持合并回系统的计划。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Marya将继续进行复制副本测试，并尝试将其合并到Merger。</li><li>讨论性能测试用例的设计和实现。</li><li>继续进行对象存储的设计和开发。</li><li>Suri将完成Crimson中安全类和对象类的实现。</li><li>Rida将讨论Sitar输入缓冲区的实现。</li><li>Comment将研究使用Python或批处理代码驱动测试。</li><li>Milan将合并UNIX域套接字支持。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了Crimson II、Crimson Messenger、Sister、Blue Store、Innings、Merger、TD Site、SMO、Sitar、输入缓冲区等关键术语。</li></ul>',17)])])}const u=i(n,[["render",o]]);export{m as __pageData,u as default};
